// 14/10/2026: una petición que se queda colgada en la red (Cloudflare/Pages) dejaba la página en blanco sin aviso; ahora cada carga tiene
// tiempo máximo y un reintento (el segundo intento salta la caché). Los mapas (geo/) son estáticos: usan la caché normal del navegador.
async function j(u,ms){ms=ms||30000;for(let i=0;i<2;i++){const ac=new AbortController(),t=setTimeout(()=>ac.abort(),ms);try{const r=await fetch(u,{cache:u.startsWith('geo/')?'default':(i?'reload':'no-cache'),signal:ac.signal});if(!r.ok)throw new Error(u);return await r.json()}catch(e){if(i)throw e}finally{clearTimeout(t)}}}
const SEA={},SEAU={};async function seace(cui){if(SEAU[cui])return SEAU[cui];const k=String(cui).slice(-2);if(!SEA[k])SEA[k]=j(`data/seace/${k}.json`).catch(()=>({}));const b=await SEA[k];return b[cui]||[]}
/* 29/10/2026: la página de una UE trae todos los procesos de sus CUI en un solo archivo (antes pedía hasta 40 bloques de 100 KB); si el archivo aún no existe, se cae a los bloques */
