  const bar=(l,v,pct,c)=>`<div style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;font-size:12px;font-weight:700;color:#37474F;margin-bottom:3px"><span>${l}</span><span style="color:${c}">${F(v)}${pct!=null?' · '+Math.round(pct)+'%':''}</span></div><div style="height:8px;background:#ECEFF3;border-radius:6px;overflow:hidden"><div style="height:100%;width:${pct!=null?Math.min(pct,100):100}%;background:${c}"></div></div></div>`;
  if(id==='fuentes')return RU.verDetalleResumen('🏦','POR FUENTE DE FINANCIAMIENTO',(extra&&extra.length?extra:[]).map(f=>`<div style="margin-bottom:14px"><div style="font-weight:800;color:var(--p2);font-size:12.5px;margin-bottom:4px">${f.nombre}</div>${bar('PIM',f.pim,null,'#C9A227')}${bar('Devengado',f.dev,f.pim?100*f.dev/f.pim:null,'#1B9E5A')}</div>`).join('')||'<p class="mutx">Sin fuentes con presupuesto.</p>');
  if(id==='benef')return RU.verDetalleResumen('👥','BENEFICIARIOS DIRECTOS',extra&&extra.total?`<p class="mutx">Hasta ${extra.total.toLocaleString('es-PE')} habitantes: es el dato de la inversión con más beneficiarios declarados en el MEF (no se suman entre inversiones porque la misma población se repite) · ${extra.conDato} de ${cuis.length} con dato registrado.</p>`:'<p class="mutx">Ninguna inversión de esta unidad ejecutora tiene el dato de beneficiarios registrado en el MEF.</p>');
  const pim1=T.pim||1,ICO={kpi:['💰','RESUMEN GENERAL'],cert:['📋','CERTIFICACIÓN'],comp:['🤝','COMPROMISO'],dev:['💵','DEVENGADO']}[id]||['📊','EJECUCIÓN PRESUPUESTAL'];
  RU.verDetalleResumen(ICO[0],ICO[1],bar('PIM',T.pim,null,'#37474F')+bar('Certificación',T.cert,100*(T.cert||0)/pim1,'#6A1B9A')+bar('Comprometido',T.comp,100*(T.comp||0)/pim1,'#00838F')+bar('Devengado',T.dev,100*(T.dev||0)/pim1,'#E65100')+(T.gir!=null?bar('Girado',T.gir,100*(T.gir||0)/pim1,'#0d366b'):'')+'<p class="mutx" style="font-size:10.5px;margin-top:6px">Fuente: Transparencia Económica, MEF</p>');
